field:
if record.examenHecho:
    # No usamos f-strings para evitar conflictos con los corchetes del JSON
    # Usamos % o .format()
    opciones = "general, ortodoncia, endodoncia, periodoncia, odontopediatria, cirugia, implantologia, prostodoncia, estetica, diagnostico"
    hoy = str(datetime.date.today())

    prompt = """
    Analiza este texto médico: '%s'
    Extrae la información y responde ÚNICAMENTE en formato JSON plano:
    {
        "tipServ": "debe ser uno de estos valores: %s",
        "motivo": "resumen muy breve",
        "fechaHistoria": "formato YYYY-MM-DD",
        "consultorio": "solo el número entero"
    }
    Reglas:
    - Si no hay fecha, usa hoy: %s
    - Si no hay consultorio, pon null.
    """ % (record.examenHecho, opciones, hoy)

    try:
        # Llamada a la IA de Odoo Enterprise
        # json ya está disponible en el contexto, no hace falta importarlo
        response = record.env['iap.account']._get_chatgpt_response(prompt)

        data = json.loads(response)

        vals = {}
        if data.get('tipServ'): 
            vals['tipServ'] = data['tipServ']
        if data.get('motivo'): 
            vals['motivo'] = data['motivo']
        if data.get('fechaHistoria'): 
            vals['fechaHistoria'] = data['fechaHistoria']
        if data.get('consultorio'):
            try: 
                vals['consultorio'] = int(data['consultorio'])
            except: 
                pass

        record.write(vals)
    except Exception as e:
        raise UserError("La IA no pudo procesar el texto. Error: " + str(e))
